@dataclass(frozen=True)
class Message:
    key: str
    params: dict = field(default_factory=dict)

    def text(self, language: str = "sv-SE") -> str:
        index = 1 if language == "en-US" else 0
        values = {k: v.text(language) if isinstance(v, Message) else v for k, v in self.params.items()}
        return MESSAGES[self.key][index].format(**values)

    def __str__(self) -> str:
        return self.text()


def msg(key: str, **params) -> Message:
    if key not in MESSAGES:
        raise KeyError(f"Missing translation key: {key}")
    return Message(key, params)


def category_label(label: str, language: str) -> str:
    return label.replace("_", "/").replace("(", " (")
